     1→/* ─── Design Tokens ─────────────────────────────────────────────────────── */
     2→:root {
     3→  --bg-deep:       #050a13;
     4→  --bg-card:       #0d1626;
     5→  --bg-input:      #111d30;
     6→  --bg-user:       #1a3a6e;
     7→  --bg-bot:        #0d1e35;
     8→  --border:        rgba(99, 160, 255, 0.12);
     9→  --border-focus:  rgba(99, 160, 255, 0.45);
    10→  --text-primary:  #e8f0ff;
    11→  --text-secondary:#8baad4;
    12→  --text-muted:    #4a6280;
    13→  --accent:        #5b9cf6;
    14→  --accent-hover:  #7ab3ff;
    15→  --accent-glow:   rgba(91, 156, 246, 0.25);
    16→  --chip-bg:       rgba(91, 156, 246, 0.08);
    17→  --chip-border:   rgba(91, 156, 246, 0.22);
    18→  --chip-hover:    rgba(91, 156, 246, 0.18);
    19→  --error-bg:      rgba(220, 53, 69, 0.12);
    20→  --error-border:  rgba(220, 53, 69, 0.3);
    21→  --error-text:    #ff7b8a;
    22→  --radius-sm:     8px;
    23→  --radius-md:     14px;
    24→  --radius-lg:     20px;
    25→  --font-ui:       'Inter', system-ui, sans-serif;
    26→  --font-brand:    'Space Grotesk', system-ui, sans-serif;
    27→  --font-mono:     'SF Mono', 'Fira Code', 'Cascadia Code', monospace;
    28→  --header-h:      62px;
    29→  --max-w:         740px;
    30→}
    31→
    32→/* ─── Reset & Base ───────────────────────────────────────────────────────── */
    33→*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    34→html { height: 100%; }
    35→
    36→body {
    37→  height: 100%;
    38→  font-family: var(--font-ui);
    39→  background: var(--bg-deep);
    40→  color: var(--text-primary);
    41→  overflow: hidden;
    42→}
    43→
    44→/* ─── Starfield Canvas ───────────────────────────────────────────────────── */
    45→#starfield {
    46→  position: fixed;
    47→  inset: 0;
    48→  z-index: 0;
    49→  pointer-events: none;
    50→}
    51→
    52→/* ─── Nebula Overlay ─────────────────────────────────────────────────────── */
    53→.nebula {
    54→  position: fixed;
    55→  inset: 0;
    56→  z-index: 0;
    57→  pointer-events: none;
    58→  background:
    59→    radial-gradient(ellipse 65% 55% at 15% 85%, rgba(88, 28, 135, 0.13) 0%, transparent 60%),
    60→    radial-gradient(ellipse 55% 45% at 85% 15%, rgba(14, 116, 144, 0.10) 0%, transparent 55%),
    61→    radial-gradient(ellipse 45% 65% at 55% 50%, rgba(30, 58, 138, 0.07) 0%, transparent 70%);
    62→}
    63→
    64→/* ─── App Shell ──────────────────────────────────────────────────────────── */
    65→.app {
    66→  position: relative;
    67→  z-index: 1;
    68→  display: flex;
    69→  flex-direction: column;
    70→  height: 100vh;
    71→  height: 100dvh;
    72→}
    73→
    74→/* ─── Header ─────────────────────────────────────────────────────────────── */
    75→.header {
    76→  height: var(--header-h);
    77→  border-bottom: 1px solid var(--border);
    78→  background: rgba(5, 10, 19, 0.85);
    79→  backdrop-filter: blur(12px);
    80→  -webkit-backdrop-filter: blur(12px);
    81→  flex-shrink: 0;
    82→}
    83→
    84→.header-inner {
    85→  max-width: var(--max-w);
    86→  margin: 0 auto;
    87→  height: 100%;
    88→  padding: 0 20px;
    89→  display: flex;
    90→  align-items: center;
    91→  justify-content: space-between;
    92→}
    93→
    94→.brand {
    95→  display: flex;
    96→  align-items: center;
    97→  gap: 10px;
    98→}
    99→
   100→.brand-icon {
   101→  font-size: 1.5rem;
   102→  animation: bob 3s ease-in-out infinite;
   103→  display: inline-block;
   104→}
   105→
   106→@keyframes bob {
   107→  0%, 100% { transform: translateY(0); }
   108→  50%       { transform: translateY(-4px); }
   109→}
   110→
   111→.brand-name {
   112→  font-family: var(--font-brand);
   113→  font-size: 1.2rem;
   114→  font-weight: 700;
   115→  color: var(--text-primary);
   116→  letter-spacing: -0.3px;
   117→}
   118→
   119→.header-right {
   120→  display: flex;
   121→  align-items: center;
   122→  gap: 12px;
   123→}
   124→
   125→.brand-tagline {
   126→  font-size: 0.75rem;
   127→  color: var(--text-muted);
   128→  font-weight: 500;
   129→  letter-spacing: 0.5px;
   130→  text-transform: uppercase;
   131→}
   132→
   133→/* ─── Icon Button (clear / reset) ───────────────────────────────────────── */
   134→.icon-btn {
   135→  width: 34px;
   136→  height: 34px;
   137→  border-radius: 50%;
   138→  border: 1px solid var(--border);
   139→  background: rgba(91, 156, 246, 0.06);
   140→  color: var(--text-muted);
   141→  cursor: pointer;
   142→  display: flex;
   143→  align-items: center;
   144→  justify-content: center;
   145→  transition: background 0.18s, border-color 0.18s, color 0.18s, transform 0.12s;
   146→  flex-shrink: 0;
   147→}
   148→
   149→.icon-btn:hover {
   150→  background: rgba(91, 156, 246, 0.14);
   151→  border-color: var(--border-focus);
   152→  color: var(--accent);
   153→  transform: scale(1.08);
   154→}
   155→
   156→.icon-btn:active { transform: scale(0.96); }
   157→
   158→/* ─── Chat Container ─────────────────────────────────────────────────────── */
   159→.chat-container {
   160→  flex: 1;
   161→  overflow-y: auto;
   162→  scroll-behavior: smooth;
   163→  padding: 24px 20px;
   164→  max-width: var(--max-w);
   165→  width: 100%;
   166→  margin: 0 auto;
   167→}
   168→
   169→.chat-container::-webkit-scrollbar { width: 5px; }
   170→.chat-container::-webkit-scrollbar-track { background: transparent; }
   171→.chat-container::-webkit-scrollbar-thumb { background: var(--border); border-radius: 99px; }
   172→
   173→/* ─── Welcome State ──────────────────────────────────────────────────────── */
   174→.welcome-state {
   175→  display: flex;
   176→  flex-direction: column;
   177→  align-items: center;
   178→  text-align: center;
   179→  padding: 40px 0 24px;
   180→  gap: 16px;
   181→}
   182→
   183→.welcome-graphic {
   184→  position: relative;
   185→  width: 80px;
   186→  height: 80px;
   187→  display: flex;
   188→  align-items: center;
   189→  justify-content: center;
   190→}
   191→
   192→.planet-emoji {
   193→  font-size: 3.8rem;
   194→  animation: spin-slow 20s linear infinite;
   195→  display: inline-block;
   196→}
   197→
   198→@keyframes spin-slow {
   199→  from { transform: rotate(0deg); }
   200→  to   { transform: rotate(360deg); }
   201→}
   202→
   203→.star-emoji {
   204→  position: absolute;
   205→  color: var(--accent);
   206→  font-size: 0.6rem;
   207→  animation: twinkle 2.5s ease-in-out infinite;
   208→}
   209→.s1 { top: 4px;  right: 2px;  animation-delay: 0s; }
   210→.s2 { bottom: 8px; left: 0px; animation-delay: 0.8s; }
   211→.s3 { top: 50%;  left: -6px;  animation-delay: 1.6s; }
   212→
   213→@keyframes twinkle {
   214→  0%, 100% { opacity: 0.3; transform: scale(0.8); }
   215→  50%       { opacity: 1;   transform: scale(1.4); }
   216→}
   217→
   218→.welcome-title {
   219→  font-family: var(--font-brand);
   220→  font-size: 1.9rem;
   221→  font-weight: 700;
   222→  color: var(--text-primary);
   223→  letter-spacing: -0.5px;
   224→}
   225→
   226→.welcome-sub {
   227→  font-size: 0.95rem;
   228→  color: var(--text-secondary);
   229→  max-width: 420px;
   230→  line-height: 1.6;
   231→}
   232→
   233→/* ─── Space Fact ─────────────────────────────────────────────────────────── */
   234→.space-fact {
   235→  font-size: 0.82rem;
   236→  color: var(--text-secondary);
   237→  background: rgba(91, 156, 246, 0.07);
   238→  border: 1px solid rgba(91, 156, 246, 0.16);
   239→  border-radius: var(--radius-md);
   240→  padding: 9px 16px;
   241→  max-width: 440px;
   242→  line-height: 1.5;
   243→  animation: fade-in 0.6s ease-out;
   244→}
   245→
   246→@keyframes fade-in {
   247→  from { opacity: 0; transform: translateY(4px); }
   248→  to   { opacity: 1; transform: translateY(0); }
   249→}
   250→
   251→/* ─── Suggestion Chips ───────────────────────────────────────────────────── */
   252→.suggestions {
   253→  display: flex;
   254→  flex-wrap: wrap;
   255→  gap: 10px;
   256→  justify-content: center;
   257→  max-width: 560px;
   258→  margin-top: 4px;
   259→}
   260→
   261→.chip {
   262→  font-family: var(--font-ui);
   263→  font-size: 0.82rem;
   264→  font-weight: 500;
   265→  color: var(--accent);
   266→  background: var(--chip-bg);
   267→  border: 1px solid var(--chip-border);
   268→  border-radius: 99px;
   269→  padding: 7px 15px;
   270→  cursor: pointer;
   271→  transition: background 0.18s, border-color 0.18s, color 0.18s, transform 0.12s;
   272→  white-space: nowrap;
   273→}
   274→
   275→.chip:hover {
   276→  background: var(--chip-hover);
   277→  border-color: var(--accent);
   278→  color: var(--accent-hover);
   279→  transform: translateY(-1px);
   280→}
   281→
   282→.chip:active { transform: translateY(0); }
   283→
   284→/* ─── Messages ───────────────────────────────────────────────────────────── */
   285→.messages {
   286→  display: flex;
   287→  flex-direction: column;
   288→  gap: 18px;
   289→}
   290→
   291→.message {
   292→  display: flex;
   293→  gap: 12px;
   294→  animation: slide-in 0.22s ease-out;
   295→}
   296→
   297→@keyframes slide-in {
   298→  from { opacity: 0; transform: translateY(8px); }
   299→  to   { opacity: 1; transform: translateY(0); }
   300→}
   301→
   302→.message.user { flex-direction: row-reverse; }
   303→
   304→.avatar {
   305→  width: 34px;
   306→  height: 34px;
   307→  border-radius: 50%;
   308→  display: flex;
   309→  align-items: center;
   310→  justify-content: center;
   311→  font-size: 1rem;
   312→  flex-shrink: 0;
   313→  margin-top: 2px;
   314→}
   315→
   316→.message.user .avatar { background: var(--bg-user); border: 1px solid rgba(99,160,255,0.3); }
   317→.message.bot  .avatar { background: var(--bg-card); border: 1px solid var(--border); }
   318→
   319→/* ─── Bubble Wrap ────────────────────────────────────────────────────────── */
   320→.bubble-wrap {
   321→  display: flex;
   322→  flex-direction: column;
   323→  max-width: 82%;
   324→  gap: 5px;
   325→}
   326→
   327→.message.user .bubble-wrap { align-items: flex-end; }
   328→
   329→.bubble {
   330→  padding: 13px 17px;
   331→  border-radius: var(--radius-md);
   332→  font-size: 0.92rem;
   333→  line-height: 1.65;
   334→  word-break: break-word;
   335→}
   336→
   337→.message.user .bubble {
   338→  background: var(--bg-user);
   339→  border: 1px solid rgba(99,160,255,0.22);
   340→  border-bottom-right-radius: var(--radius-sm);
   341→  color: var(--text-primary);
   342→}
   343→
   344→.message.bot .bubble {
   345→  background: var(--bg-bot);
   346→  border: 1px solid var(--border);
   347→  border-bottom-left-radius: var(--radius-sm);
   348→  color: var(--text-primary);
   349→}
   350→
   351→/* ─── Bubble Footer (timestamp + copy) ───────────────────────────────────── */
   352→.bubble-footer {
   353→  display: flex;
   354→  align-items: center;
   355→  justify-content: space-between;
   356→  padding: 0 3px;
   357→  gap: 12px;
   358→}
   359→
   360→.msg-time {
   361→  font-size: 0.67rem;
   362→  color: var(--text-muted);
   363→  flex-shrink: 0;
   364→}
   365→
   366→.copy-btn {
   367→  background: none;
   368→  border: none;
   369→  cursor: pointer;
   370→  color: var(--text-muted);
   371→  padding: 3px 5px;
   372→  border-radius: 5px;
   373→  display: flex;
   374→  align-items: center;
   375→  gap: 4px;
   376→  font-size: 0.68rem;
   377→  transition: color 0.15s, background 0.15s;
   378→}
   379→
   380→.copy-btn:hover {
   381→  color: var(--accent);
   382→  background: rgba(91, 156, 246, 0.1);
   383→}
   384→
   385→.copy-btn.copied { color: #4ade80; }
   386→
   387→/* ─── Markdown Prose ─────────────────────────────────────────────────────── */
   388→.bubble.prose p              { margin-bottom: 0.55em; }
   389→.bubble.prose p:last-child   { margin-bottom: 0; }
   390→.bubble.prose strong         { color: var(--accent-hover); font-weight: 600; }
   391→.bubble.prose em             { font-style: italic; color: var(--text-secondary); }
   392→.bubble.prose ul,
   393→.bubble.prose ol             { padding-left: 1.5em; margin: 0.4em 0; }
   394→.bubble.prose li             { margin-bottom: 0.25em; }
   395→.bubble.prose li::marker     { color: var(--accent); }
   396→.bubble.prose code           {
   397→  font-family: var(--font-mono);
   398→  font-size: 0.83em;
   399→  background: rgba(91, 156, 246, 0.1);
   400→  border: 1px solid rgba(91, 156, 246, 0.18);
   401→  border-radius: 4px;
   402→  padding: 1px 5px;
   403→  color: var(--accent-hover);
   404→}
   405→.bubble.prose pre            {
   406→  background: rgba(0, 0, 0, 0.45);
   407→  border: 1px solid var(--border);
   408→  border-radius: var(--radius-sm);
   409→  padding: 12px 14px;
   410→  overflow-x: auto;
   411→  margin: 0.6em 0;
   412→}
   413→.bubble.prose pre code       {
   414→  background: none;
   415→  border: none;
   416→  padding: 0;
   417→  font-size: 0.82em;
   418→  color: var(--text-primary);
   419→}
   420→.bubble.prose h1,
   421→.bubble.prose h2,
   422→.bubble.prose h3             {
   423→  font-family: var(--font-brand);
   424→  font-weight: 700;
   425→  margin: 0.6em 0 0.3em;
   426→  color: var(--text-primary);
   427→}
   428→.bubble.prose h1             { font-size: 1.1em; }
   429→.bubble.prose h2             { font-size: 1.0em; }
   430→.bubble.prose h3             { font-size: 0.95em; }
   431→.bubble.prose blockquote     {
   432→  border-left: 3px solid var(--accent);
   433→  padding-left: 12px;
   434→  margin: 0.5em 0;
   435→  color: var(--text-secondary);
   436→  font-style: italic;
   437→}
   438→.bubble.prose a              { color: var(--accent); text-decoration: underline; }
   439→
   440→/* ─── Typing Indicator ───────────────────────────────────────────────────── */
   441→.typing-bubble {
   442→  background: var(--bg-bot);
   443→  border: 1px solid var(--border);
   444→  border-radius: var(--radius-md);
   445→  border-bottom-left-radius: var(--radius-sm);
   446→  padding: 14px 18px;
   447→  display: flex;
   448→  gap: 5px;
   449→  align-items: center;
   450→}
   451→
   452→.dot {
   453→  width: 7px;
   454→  height: 7px;
   455→  background: var(--text-muted);
   456→  border-radius: 50%;
   457→  animation: bounce-dot 1.3s ease-in-out infinite;
   458→}
   459→.dot:nth-child(2) { animation-delay: 0.2s; }
   460→.dot:nth-child(3) { animation-delay: 0.4s; }
   461→
   462→@keyframes bounce-dot {
   463→  0%, 60%, 100% { transform: translateY(0);    opacity: 0.4; }
   464→  30%            { transform: translateY(-6px); opacity: 1;   }
   465→}
   466→
   467→.typing-label {
   468→  font-size: 0.78rem;
   469→  color: var(--text-muted);
   470→  margin-left: 8px;
   471→  font-style: italic;
   472→}
   473→
   474→/* ─── Error Bubble ───────────────────────────────────────────────────────── */
   475→.error-bubble {
   476→  background: var(--error-bg);
   477→  border: 1px solid var(--error-border);
   478→  border-radius: var(--radius-md);
   479→  border-bottom-left-radius: var(--radius-sm);
   480→  padding: 12px 16px;
   481→  color: var(--error-text);
   482→  font-size: 0.88rem;
   483→  display: flex;
   484→  align-items: center;
   485→  gap: 8px;
   486→}
   487→
   488→/* ─── Scroll FAB ─────────────────────────────────────────────────────────── */
   489→.scroll-fab {
   490→  position: fixed;
   491→  bottom: 130px;
   492→  right: 24px;
   493→  width: 38px;
   494→  height: 38px;
   495→  border-radius: 50%;
   496→  border: 1px solid var(--border);
   497→  background: rgba(13, 22, 38, 0.92);
   498→  backdrop-filter: blur(10px);
   499→  -webkit-backdrop-filter: blur(10px);
   500→  color: var(--accent);
   501→  cursor: pointer;
   502→  display: flex;
   503→  align-items: center;
   504→  justify-content: center;
   505→  z-index: 10;
   506→  transition: opacity 0.2s, transform 0.2s, background 0.18s;
   507→  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
   508→}
   509→
   510→.scroll-fab:hover {
   511→  background: rgba(91, 156, 246, 0.15);
   512→  transform: translateY(-2px);
   513→}
   514→
   515→.scroll-fab.hidden {
   516→  opacity: 0;
   517→  pointer-events: none;
   518→  transform: translateY(8px);
   519→}
   520→
   521→/* ─── Input Area ─────────────────────────────────────────────────────────── */
   522→.input-area {
   523→  flex-shrink: 0;
   524→  background: rgba(5, 10, 19, 0.9);
   525→  backdrop-filter: blur(14px);
   526→  -webkit-backdrop-filter: blur(14px);
   527→  border-top: 1px solid var(--border);
   528→  padding: 14px 20px 16px;
   529→}
   530→
   531→.input-form {
   532→  max-width: var(--max-w);
   533→  margin: 0 auto;
   534→}
   535→
   536→.input-wrap {
   537→  display: flex;
   538→  align-items: flex-end;
   539→  gap: 10px;
   540→  background: var(--bg-input);
   541→  border: 1px solid var(--border);
   542→  border-radius: var(--radius-lg);
   543→  padding: 10px 10px 10px 16px;
   544→  transition: border-color 0.2s, box-shadow 0.2s;
   545→}
   546→
   547→.input-wrap:focus-within {
   548→  border-color: var(--border-focus);
   549→  box-shadow: 0 0 0 3px var(--accent-glow);
   550→}
   551→
   552→.input-field {
   553→  flex: 1;
   554→  background: transparent;
   555→  border: none;
   556→  outline: none;
   557→  color: var(--text-primary);
   558→  font-family: var(--font-ui);
   559→  font-size: 0.93rem;
   560→  line-height: 1.5;
   561→  resize: none;
   562→  max-height: 140px;
   563→  overflow-y: auto;
   564→}
   565→
   566→.input-field::placeholder { color: var(--text-muted); }
   567→
   568→.input-field::-webkit-scrollbar { width: 4px; }
   569→.input-field::-webkit-scrollbar-thumb { background: var(--border); border-radius: 99px; }
   570→
   571→.send-btn {
   572→  width: 38px;
   573→  height: 38px;
   574→  border-radius: 50%;
   575→  border: none;
   576→  background: var(--accent);
   577→  color: white;
   578→  cursor: pointer;
   579→  display: flex;
   580→  align-items: center;
   581→  justify-content: center;
   582→  flex-shrink: 0;
   583→  transition: background 0.18s, transform 0.12s, opacity 0.18s;
   584→}
   585→
   586→.send-btn:hover  { background: var(--accent-hover); transform: scale(1.06); }
   587→.send-btn:active { transform: scale(0.96); }
