   146→    @keyframes shine { to { background-position: 250% center; } }
   147→    .splash-tagline {
   148→      font-size: .72rem; color: #c9dbf3;
   149→      letter-spacing: .12em; text-transform: uppercase;
   150→      animation: blurIn .6s ease both; animation-delay: 1.15s; opacity: 0;
   151→    }
   152→    .splash-bar {
   153→      width: 160px; height: 2px;
   154→      background: rgba(91,156,246,.15); border-radius: 99px; overflow: hidden;
   155→      animation: blurIn .4s ease both; animation-delay: .9s; opacity: 0;
   156→    }
   157→    .splash-fill { height:100%; width:0%; border-radius:99px;
   158→      background: linear-gradient(90deg, var(--accent), #a78bfa); }
   159→    .splash-skip {
   160→      font-size: .68rem; color: #9eb7d8;
   161→      animation: blurIn .5s ease both; animation-delay: 1.4s; opacity: 0;
   162→    }
   163→
   164→    /* ─── App wrapper ────────────────────────────────────────────────────── */
   165→    #app-wrap {
   166→      position: relative; z-index: 2;
   167→      opacity: 0; transition: opacity .8s ease .15s;
   168→      height: 100vh; height: 100dvh;
   169→      background: transparent;
   170→    }
   171→    #app-wrap.show { opacity: 1; }
   172→
   173→    /* ════════════════════════════════════════════════════════════════════════
   174→       APP SHELL
   175→    ════════════════════════════════════════════════════════════════════════ */
   176→    .app {
   177→      display: flex; flex-direction: column;
   178→      height: 100vh; height: 100dvh;
   179→      background: transparent;
   180→    }
   181→
   182→    /* ─── Header ─────────────────────────────────────────────────────────── */
   183→    .header {
   184→      position: sticky; top: 0; z-index: 10;
   185→      height: var(--header-h); flex-shrink: 0;
   186→      border-bottom: 1px solid var(--border);
   187→      background: linear-gradient(180deg, rgba(5,10,19,.78) 0%, rgba(5,10,19,.56) 100%);
   188→      backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
   189→    }
   190→    .header-inner {
   191→      max-width: var(--max-w); margin: 0 auto; height: 100%;
   192→      padding: 0 var(--px);
   193→      display: flex; align-items: center; justify-content: space-between;
   194→    }
   195→    .brand { display:flex; align-items:center; gap:10px; }
   196→    .brand-icon { font-size:1.45rem; display:inline-block; animation:bob 3s ease-in-out infinite; }
   197→    @keyframes bob { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-4px)} }
   198→    .brand-name {
   199→      font-family:var(--font-brand); font-size:1.15rem; font-weight:700;
   200→      color:#f1f7ff; letter-spacing:-.3px;
   201→    }
   202→    .header-right { display:flex; align-items:center; gap:12px; }
   203→    .brand-tagline {
   204→      font-size:.74rem; color:#a9c1e1;
   205→      font-weight:500; letter-spacing:.5px; text-transform:uppercase;
   206→    }
   207→    .icon-btn {
   208→      width:34px; height:34px; border-radius:50%;
   209→      border:1px solid var(--border); background:rgba(91,156,246,.06);
   210→      color:var(--text-muted); cursor:pointer;
   211→      display:flex; align-items:center; justify-content:center;
   212→      transition:background .18s, border-color .18s, color .18s, transform .12s; flex-shrink:0;
   213→    }
   214→    .icon-btn:hover { background:rgba(91,156,246,.14); border-color:var(--border-focus); color:var(--accent); transform:scale(1.08); }
   215→    .icon-btn:active { transform:scale(.96); }
   216→
   217→    /* ════════════════════════════════════════════════════════════════════════
   218→       LANDING VIEW  —  welcome + input CENTERED (ChatGPT / Claude pattern)
   219→    ════════════════════════════════════════════════════════════════════════ */
   220→    .landing {
   221→      flex: 1; overflow-y: auto; overflow-x: hidden;
   222→      display: flex; flex-direction: column;
   223→      align-items: center; justify-content: center;
   224→      padding: 20px var(--px);
   225→      padding-bottom: max(20px, var(--safe-b));
   226→      background: transparent;
   227→    }
   228→    .landing::-webkit-scrollbar { width:5px; }
   229→    .landing::-webkit-scrollbar-track { background:transparent; }
   230→    .landing::-webkit-scrollbar-thumb { background:var(--border); border-radius:99px; }
   231→    .landing-body {
   232→      width:100%; max-width:var(--max-w);
   233→      display:flex; flex-direction:column; align-items:center;
   234→      background: transparent;
   235→    }
   236→    .welcome-block {
   237→      display:flex; flex-direction:column; align-items:center;
   238→      text-align:center; gap:14px; width:100%; padding-bottom:28px;
   239→    }
   240→    .welcome-graphic {
   241→      position:relative; width:90px; height:90px;
   242→      display:flex; align-items:center; justify-content:center;
   243→    }
   244→    .planet-emoji { font-size:4.2rem; display:inline-block; animation:spin-slow 20s linear infinite; }
   245→    @keyframes spin-slow { from{transform:rotate(0deg)} to{transform:rotate(360deg)} }
   246→    .star-emoji { position:absolute; color:var(--accent); font-size:.6rem; animation:twinkle 2.5s ease-in-out infinite; }
   247→    .s1{top:4px;right:2px;animation-delay:0s}
   248→    .s2{bottom:8px;left:0;animation-delay:.8s}
   249→    .s3{top:50%;left:-6px;animation-delay:1.6s}
   250→    @keyframes twinkle { 0%,100%{opacity:.3;transform:scale(.8)} 50%{opacity:1;transform:scale(1.4)} }
   251→    .welcome-title {
   252→      font-family:var(--font-brand); font-size:clamp(1.6rem,4vw,2.1rem);
   253→      font-weight:700; color:var(--text-primary); letter-spacing:-.5px;
   254→      text-shadow: 0 0 30px rgba(91,156,246,.25);
   255→    }
   256→    .welcome-sub {
   257→      font-size:clamp(.88rem,2vw,.97rem); color:var(--text-secondary);
   258→      max-width:440px; line-height:1.65;
   259→    }
   260→    .space-fact {
   261→      font-size:clamp(.78rem,1.8vw,.84rem); color:var(--text-secondary);
   262→      background:rgba(91,156,246,.06); border:1px solid rgba(91,156,246,.14);
   263→      border-radius:var(--r-md); padding:10px 18px;
   264→      max-width:480px; line-height:1.55;
   265→      animation:fadeUp .6s ease-out both;
   266→    }
   267→    @keyframes fadeUp { from{opacity:0;transform:translateY(6px)} to{opacity:1;transform:translateY(0)} }
   268→    .suggestions {
   269→      display:flex; flex-wrap:wrap; gap:9px; justify-content:center;
   270→      max-width:560px; margin-top:2px;
   271→    }
   272→    .chip {
   273→      font-family:var(--font-ui); font-size:.81rem; font-weight:500;
   274→      color:var(--accent); background:var(--chip-bg);
   275→      border:1px solid var(--chip-border); border-radius:99px;
   276→      padding:7px 16px; cursor:pointer; white-space:nowrap;
   277→      transition:background .18s, border-color .18s, color .18s, transform .12s, box-shadow .18s;
   278→    }
   279→    .chip:hover {
   280→      background:var(--chip-hover); border-color:var(--accent); color:var(--accent-hover);
   281→      transform:translateY(-1px); box-shadow:0 4px 14px rgba(91,156,246,.18);
   282→    }
   283→    .chip:active { transform:translateY(0); }
   284→
   285→    /* ════════════════════════════════════════════════════════════════════════
   286→       SHARED INPUT FORM
   287→    ════════════════════════════════════════════════════════════════════════ */
   288→    .input-form { width:100%; max-width:var(--max-w); margin:0 auto; }
   289→
   290→    .input-wrap {
   291→      display:flex;
   292→      align-items:center;           /* ← centered: fixes placeholder alignment */
   293→      gap:10px;
   294→      background:rgba(13,27,46,.85);
   295→      border:1.5px solid var(--border);
   296→      border-radius:var(--r-xl);
   297→      padding:11px 12px 11px 18px;
   298→      transition:border-color .2s, box-shadow .25s;
   299→      box-shadow:0 2px 24px rgba(0,0,0,.35), 0 0 0 0 transparent;
   300→      backdrop-filter:blur(8px); -webkit-backdrop-filter:blur(8px);
   301→    }
   302→    .input-wrap:focus-within {
   303→      border-color:var(--border-focus);
   304→      box-shadow:0 0 0 3px var(--accent-glow), 0 4px 28px rgba(0,0,0,.4);
   305→    }
   306→    .input-field {
   307→      flex:1; background:transparent; border:none; outline:none;
   308→      color:var(--text-primary); font-family:var(--font-ui);
   309→      font-size:1rem;           /* 16px — prevents iOS auto-zoom */
   310→      line-height:1.55; resize:none;
   311→      min-height:24px; max-height:160px; overflow-y:auto;
   312→      padding:0;                /* no extra padding — keeps placeholder perfectly centered */
   313→      vertical-align:middle;
   314→    }
   315→    .input-field::placeholder { color:var(--text-muted); }
   316→    .input-field::-webkit-scrollbar { width:4px; }
   317→    .input-field::-webkit-scrollbar-thumb { background:var(--border); border-radius:99px; }
   318→
   319→    .send-btn {
   320→      width:40px; height:40px; border-radius:50%; border:none; flex-shrink:0;
   321→      background:var(--accent); color:#fff; cursor:pointer;
   322→      display:flex; align-items:center; justify-content:center;
   323→      transition:background .18s, transform .12s, box-shadow .18s;
   324→      box-shadow:0 2px 12px rgba(91,156,246,.4);
   325→    }
   326→    .send-btn:hover  { background:var(--accent-hover); transform:scale(1.07); box-shadow:0 4px 18px rgba(91,156,246,.5); }
   327→    .send-btn:active { transform:scale(.94); }
   328→    .send-btn:disabled { opacity:.35; cursor:not-allowed; transform:none; box-shadow:none; }
   329→
   330→    .input-meta {
   331→      display:flex; align-items:center; justify-content:space-between;
   332→      margin-top:8px; padding:0 4px;
   333→    }
   334→    .disclaimer { font-size:.7rem; color:#97b2d4; line-height:1.4; }
   335→    .char-count {
   336→      font-size:.68rem; color:#89a5ca; flex-shrink:0;
   337→      font-variant-numeric:tabular-nums; transition:color .2s;
   338→    }
   339→    .char-count.warn  { color:#f59e0b; }
   340→    .char-count.limit { color:var(--error-text); }
   341→
   342→    /* Landing input dock: give the input a bit of breathing room */
   343→    #landingInputDock {
   344→      width:100%;
   345→      background: transparent;
   346→    }
   347→
   348→    /* ════════════════════════════════════════════════════════════════════════
   349→       CHAT VIEW
   350→    ════════════════════════════════════════════════════════════════════════ */
   351→    .chat-view {
   352→      flex:1;
   353→      display:none;
   354→      flex-direction:column;
   355→      overflow:hidden;
   356→      background: transparent;
   357→    }
   358→    .chat-view.active { display:flex; }
   359→
   360→    .chat-scroll {
   361→      flex:1; overflow-y:auto; overflow-x:hidden;
   362→      padding:24px var(--px) 8px;
   363→      overscroll-behavior-y:contain; scroll-behavior:smooth;
   364→      background: transparent;
   365→    }
   366→    .chat-scroll::-webkit-scrollbar { width:5px; }
   367→    .chat-scroll::-webkit-scrollbar-track { background:transparent; }
   368→    .chat-scroll::-webkit-scrollbar-thumb { background:var(--border); border-radius:99px; }
   369→
   370→    /* Messages */
   371→    .messages {
   372→      display:flex;
   373→      flex-direction:column;
   374→      gap:20px;
   375→      max-width:var(--max-w);
   376→      margin:0 auto;
   377→      background: transparent;
   378→    }
   379→    .message { display:flex; gap:12px; animation:slideIn .22s ease-out; }
   380→    @keyframes slideIn { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:translateY(0)} }
   381→    .message.user { flex-direction:row-reverse; }
   382→
   383→    .avatar {
   384→      width:34px; height:34px; border-radius:50%; flex-shrink:0; margin-top:2px;
   385→      display:flex; align-items:center; justify-content:center; font-size:.95rem;
   386→    }
   387→    .message.user .avatar { background:var(--bg-user); border:1px solid rgba(99,160,255,.3); }
   388→    .message.bot  .avatar { background:var(--bg-card); border:1px solid var(--border); }
   389→
   390→    .bubble-wrap { display:flex; flex-direction:column; max-width:min(82%,620px); gap:5px; }
   391→    .message.user .bubble-wrap { align-items:flex-end; }
   392→    .message.bot  .bubble-wrap { align-items:flex-start; }
   393→
   394→    .bubble {
   395→      padding:13px 17px; border-radius:var(--r-md);
   396→      font-size:.91rem; line-height:1.68; word-break:break-word; text-align:left;
   397→    }
   398→    .message.user .bubble {
   399→      background:var(--bg-user); border:1px solid rgba(99,160,255,.22);
   400→      border-bottom-right-radius:var(--r-sm); color:var(--text-primary);
   401→    }
   402→    .message.bot .bubble {
   403→      background:var(--bg-bot); border:1px solid var(--border);
   404→      border-bottom-left-radius:var(--r-sm); color:var(--text-primary);
   405→    }
   406→
   407→    .bubble-footer { display:flex; align-items:center; gap:6px; padding:0 3px; }
   408→    .message.user .bubble-footer { justify-content:flex-end; }
   409→    .message.bot  .bubble-footer { justify-content:flex-start; }
   410→    .msg-time { font-size:.65rem; color:#91add0; flex-shrink:0; }
   411→
   412→    .copy-btn,.speak-btn {
   413→      background:none; border:none; cursor:pointer;
   414→      color:#97b3d6; padding:4px 8px; border-radius:6px;
   415→      display:flex; align-items:center; gap:4px;
   416→      font-size:.67rem; font-family:var(--font-ui);
   417→      transition:color .15s, background .15s; white-space:nowrap; min-height:28px;
   418→    }
   419→    .copy-btn:hover,.speak-btn:hover { color:var(--accent); background:rgba(91,156,246,.10); }
   420→    .copy-btn.copied { color:#4ade80; }
   421→    .speak-btn.speaking { color:#f59e0b; background:rgba(245,158,11,.08); }
   422→    @keyframes speakPulse { 0%,100%{opacity:1} 50%{opacity:.35} }
   423→    .speak-btn.speaking svg { animation:speakPulse 1.1s ease-in-out infinite; }
   424→
   425→    /* Markdown prose */
   426→    .bubble.prose p { margin-bottom:.55em; }
   427→    .bubble.prose p:last-child { margin-bottom:0; }
   428→    .bubble.prose strong { color:var(--accent-hover); font-weight:600; }
   429→    .bubble.prose em { font-style:italic; color:#b3cae8; }
   430→    .bubble.prose ul,.bubble.prose ol { padding-left:1.5em; margin:.4em 0; }
   431→    .bubble.prose li { margin-bottom:.25em; }
   432→    .bubble.prose li::marker { color:var(--accent); }
   433→    .bubble.prose code {
   434→      font-family:var(--font-mono); font-size:.82em;
   435→      background:rgba(91,156,246,.1); border:1px solid rgba(91,156,246,.18);
   436→      border-radius:4px; padding:1px 5px; color:var(--accent-hover);
   437→    }
   438→    .bubble.prose pre {
   439→      background:rgba(0,0,0,.5); border:1px solid var(--border);
   440→      border-radius:var(--r-sm); padding:12px 14px; overflow-x:auto; margin:.6em 0;
   441→    }
   442→    .bubble.prose pre code { background:none; border:none; padding:0; font-size:.82em; color:var(--text-primary); }
   443→    .bubble.prose h1,.bubble.prose h2,.bubble.prose h3 {
   444→      font-family:var(--font-brand); font-weight:700; margin:.6em 0 .3em; color:var(--text-primary);
   445→    }
   446→    .bubble.prose h1{font-size:1.1em} .bubble.prose h2{font-size:1em} .bubble.prose h3{font-size:.95em}
   447→    .bubble.prose blockquote {
   448→      border-left:3px solid var(--accent); padding-left:12px;
   449→      margin:.5em 0; color:#b2cae8; font-style:italic;
   450→    }
   451→    .bubble.prose a { color:var(--accent); text-decoration:underline; }
   452→
   453→    /* Typing */
   454→    .typing-bubble {
   455→      background:var(--bg-bot); border:1px solid var(--border);
   456→      border-radius:var(--r-md); border-bottom-left-radius:var(--r-sm);
   457→      padding:14px 18px; display:flex; gap:5px; align-items:center;
   458→    }
   459→    .dot { width:7px; height:7px; background:var(--text-muted); border-radius:50%; animation:bounceDot 1.3s ease-in-out infinite; }
   460→    .dot:nth-child(2){animation-delay:.2s} .dot:nth-child(3){animation-delay:.4s}
   461→    @keyframes bounceDot { 0%,60%,100%{transform:translateY(0);opacity:.4} 30%{transform:translateY(-6px);opacity:1} }
   462→    .typing-label { font-size:.77rem; color:#9cb6d8; margin-left:8px; font-style:italic; }
   463→
   464→    /* Error */
   465→    .error-bubble {
   466→      background:var(--error-bg); border:1px solid var(--error-border);
   467→      border-radius:var(--r-md); border-bottom-left-radius:var(--r-sm);
   468→      padding:12px 16px; color:var(--error-text); font-size:.87rem;
   469→      display:flex; align-items:center; gap:8px;
   470→    }
   471→
   472→    /* Chat input bar */
   473→    .chat-input-bar {
   474→      flex-shrink:0;
   475→      background:linear-gradient(180deg, rgba(5,10,19,.52) 0%, rgba(5,10,19,.76) 100%);
   476→      backdrop-filter:blur(18px); -webkit-backdrop-filter:blur(18px);
   477→      border-top:1px solid var(--border);
   478→      padding:12px var(--px);
   479→      padding-bottom:max(14px, var(--safe-b));
   480→    }
   481→
   482→    /* Scroll FAB */
   483→    .scroll-fab {
   484→      position:sticky; bottom:16px; float:right;
   485→      width:36px; height:36px; border-radius:50%;
   486→      border:1px solid var(--border);
   487→      background:rgba(13,22,38,.94);
   488→      backdrop-filter:blur(10px); -webkit-backdrop-filter:blur(10px);
   489→      color:var(--accent); cursor:pointer;
   490→      display:flex; align-items:center; justify-content:center;
   491→      transition:opacity .2s, transform .2s, background .18s;
   492→      box-shadow:0 4px 16px rgba(0,0,0,.4);
   493→      margin-bottom:-36px;
   494→    }
   495→    .scroll-fab:hover { background:rgba(91,156,246,.18); transform:translateY(-2px); }
   496→    .scroll-fab.hidden { opacity:0; pointer-events:none; }
   497→
   498→    /* ─── Utilities ──────────────────────────────────────────────────────── */
   499→    .hidden { display:none !important; }
   500→
   501→    /* ════════════════════════════════════════════════════════════════════════
   502→       RESPONSIVE
   503→    ════════════════════════════════════════════════════════════════════════ */
   504→    @media (max-width: 800px)  { :root { --px: 16px; } }
   505→    @media (max-width: 600px)  {
   506→      :root { --px:12px; --header-h:54px; }
   507→      .brand-tagline { display:none; }
   508→      .welcome-title { font-size:1.4rem; }
   509→      .welcome-sub   { font-size:.87rem; max-width:none; }
   510→      .space-fact    { font-size:.77rem; max-width:none; }
   511→      .suggestions   { gap:8px; }
   512→      .chip          { font-size:.77rem; padding:6px 13px; }
   513→      .bubble-wrap   { max-width:90%; }
   514→      .bubble        { font-size:.88rem; padding:11px 14px; }
   515→      .splash-title  { font-size:clamp(2rem,11vw,3rem); }
   516→    }
   517→    @media (max-width: 380px)  {
   518→      .welcome-title { font-size:1.2rem; }
   519→      .chip          { font-size:.72rem; padding:5px 11px; }
   520→    }
   521→    @media (max-height:500px) and (orientation:landscape) {
   522→      .welcome-graphic { display:none; }
   523→      .welcome-block   { gap:10px; padding-bottom:14px; }
   524→      .landing         { justify-content:flex-start; padding-top:10px; }
   525→    }
   526→  </style>
   527→</head>
   528→<body>
   529→
   530→  <!-- Color Bends background container -->
   531→  <div id="cb-bg"></div>
   532→
   533→  <!-- ══════════════════════════════════════════
   534→       SPLASH
   535→  ══════════════════════════════════════════ -->
   536→  <div id="splash">
   537→    <div class="splash-content">
   538→      <div class="splash-rocket">🚀</div>
   539→      <h1 class="splash-title" id="splash-title"></h1>
   540→      <p class="splash-sub">Space Exploration AI</p>
   541→      <p class="splash-tagline">Powered by LLaMA 3.3 · Groq</p>
   542→      <div class="splash-bar"><div class="splash-fill" id="splash-fill"></div></div>
   543→      <span class="splash-skip">Click anywhere to skip</span>
   544→    </div>
   545→  </div>
   546→
   547→  <!-- ══════════════════════════════════════════
   548→       MAIN APP
   549→  ══════════════════════════════════════════ -->
   550→  <div id="app-wrap">
   551→    <div class="app">
   552→
   553→      <header class="header">
   554→        <div class="header-inner">
   555→          <div class="brand">
   556→            <span class="brand-icon" aria-hidden="true">🚀</span>
   557→            <span class="brand-name">CosmoBot</span>
   558→          </div>
   559→          <div class="header-right">
