   877→  /* ════════════════════════════════════════════════════════════════════════
   878→     SPLASH  (ReactBits: SplitText · BlurIn · ShinyText)
   879→  ════════════════════════════════════════════════════════════════════════ */
   880→  (function () {
   881→    const titleEl = document.getElementById('splash-title');
   882→    const fillEl  = document.getElementById('splash-fill');
   883→    const splash  = document.getElementById('splash');
   884→    const appWrap = document.getElementById('app-wrap');
   885→    const TITLE = 'COSMOBOT';
   886→    const opts = {
   887→      shuffleDirection: 'right',
   888→      duration: 350,
   889→      ease: 'cubic-bezier(.22,1,.36,1)',
   890→      shuffleTimes: 1,
   891→      stagger: 30,
   892→      respectReducedMotion: true,
   893→      scrambleCharset: 'REDACTED',
   894→    };
   895→
   896→    function randomChar(charset) {
   897→      return charset.charAt(Math.floor(Math.random() * charset.length)) || '';
   898→    }
   899→
   900→    async function buildShuffleTitle() {
   901→      if (document.fonts?.ready) {
   902→        try { await document.fonts.ready; } catch {}
   903→      }
   904→
   905→      titleEl.setAttribute('aria-label', TITLE);
   906→      titleEl.textContent = '';
   907→
   908→      const reduced =
   909→        opts.respectReducedMotion &&
   910→        window.matchMedia &&
   911→        window.matchMedia('(prefers-reduced-motion: reduce)').matches;
   912→
   913→      if (reduced) {
   914→        titleEl.textContent = TITLE;
   915→        titleEl.classList.add('is-ready');
   916→        return;
   917→      }
   918→
   919→      const tempChars = [];
   920→      for (const char of TITLE) {
   921→        const span = document.createElement('span');
   922→        span.className = 'splash-shuffle-char';
   923→        span.textContent = char;
   924→        span.style.opacity = '0';
   925→        titleEl.appendChild(span);
   926→        tempChars.push(span);
   927→      }
   928→
   929→      const measurements = tempChars.map((span) => {
   930→        const rect = span.getBoundingClientRect();
   931→        return {
   932→          width: Math.max(rect.width, 1),
   933→          height: Math.max(rect.height, 1),
   934→          text: span.textContent || '',
   935→        };
   936→      });
