   938→      titleEl.textContent = '';
   939→
   940→      const animations = [];
   941→      const oddIndices = measurements.map((_, index) => index).filter((index) => index % 2 === 1);
   942→      const evenIndices = measurements.map((_, index) => index).filter((index) => index % 2 === 0);
