   947→        const wrap = document.createElement('span');
   948→        wrap.className = 'splash-shuffle-wrap';
   949→        wrap.style.width = `${width}px`;
   950→        wrap.style.height = `${height}px`;
   951→
   952→        const strip = document.createElement('span');
   953→        strip.className = 'splash-shuffle-strip';
   954→
   955→        const original = document.createElement('span');
   956→        original.className = 'splash-shuffle-char';
   957→        original.textContent = text;
   958→        original.style.width = `${width}px`;
   959→
   960→        const copies = [original];
   961→        for (let i = 0; i < opts.shuffleTimes; i++) {
   962→          const node = document.createElement('span');
   963→          node.className = 'splash-shuffle-char';
   964→          node.textContent = randomChar(opts.scrambleCharset);
   965→          node.style.width = `${width}px`;
   966→          copies.push(node);
   967→        }
   968→
   969→        const final = document.createElement('span');
   970→        final.className = 'splash-shuffle-char';
   971→        final.textContent = text;
   972→        final.style.width = `${width}px`;
   973→        copies.push(final);
   974→
   975→        if (opts.shuffleDirection === 'right') {
   976→          const first = copies.shift();
   977→          if (first) copies.push(first);
   978→        }
   979→
   980→        strip.append(...copies);
   981→        wrap.appendChild(strip);
   982→        titleEl.appendChild(wrap);
   983→
   984→        const steps = opts.shuffleTimes + 1;
   985→        const startX = opts.shuffleDirection === 'right' ? -steps * width : 0;
   986→        const finalX = opts.shuffleDirection === 'right' ? 0 : -steps * width;
   987→        strip.style.transform = `translate3d(${startX}px, 0, 0)`;
   988→
   989→        const oddOrder = oddIndices.indexOf(index);
   990→        const evenOrder = evenIndices.indexOf(index);
   991→        const delay =
   992→          index % 2 === 1
   993→            ? Math.max(0, oddOrder) * opts.stagger
   994→            : evenBaseDelay + Math.max(0, evenOrder) * opts.stagger;
