   996→        animations.push(new Promise((resolve) => {
   997→          const anim = strip.animate(
   998→            [
   999→              { transform: `translate3d(${startX}px, 0, 0)` },
  1000→              { transform: `translate3d(${finalX}px, 0, 0)` },
  1001→            ],
  1002→            {
  1003→              duration: opts.duration,
  1004→              delay,
  1005→              easing: opts.ease,
  1006→              fill: 'forwards',
  1007→            }
  1008→          );
  1009→          anim.onfinish = () => {
  1010→            wrap.replaceChildren(final);
  1011→            final.style.width = `${width}px`;
  1012→            resolve();
  1013→          };
  1014→        }));
  1015→      });
  1016→
  1017→      titleEl.classList.add('is-ready');
  1018→      await Promise.all(animations);
  1019→    }
  1020→
  1021→    buildShuffleTitle();
